// Check for PDF
const binaryKeys = Object.keys($input.item.binary || {});
const hasPDF = binaryKeys.length > 0;

if (hasPDF) {
  const binaryKey = binaryKeys[0];

  return [{
    json: {
      has_pdf: true,
      binary_key: binaryKey
    },
    binary: $input.item.binary
  }];
}

// Get text from webhook body
const text =
  $json.body?.text ||
  $json.text ||
  "";

if (!text.trim()) {
  return [{
    json: {
      error: true,
      message: "No PDF or text provided"
    }
  }];
}

return [{
  json: {
    has_pdf: false,
    raw_text: text.trim()
  }
}];

const text =
  $json.raw_text ||
  $json.text ||
  $json.content ||
  $json.message ||
  '';

const cleanText = String(text)
  .replace(/\r/g, ' ')
  .replace(/\n/g, ' ')
  .replace(/\t/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

return [{
  json: {
    text: cleanText
  }
}];

const text =
  $json.raw_text ||
  $json.text ||
  $json.content ||
  '';
const found = new Set();
const patterns = [

  /\b(?:section|sections)\s+(\d+[A-Z]{0,2}(?:\(\d+\))?)/gi,

  /\bS\.\s*(\d+[A-Z]{0,2}(?:\(\d+\))?)/gi,

  /\bIPC\s*(\d+[A-Z]{0,2}(?:\(\d+\))?)/gi,

  /\b(\d+[A-Z]{0,2}(?:\(\d+\))?)\s*IPC\b/gi,

  /\bu\/s\s*(\d+[A-Z]{0,2}(?:\(\d+\))?)/gi,

];
for (const regex of patterns) {let match; while((match =regex.exec(text)) !== null) {
    found.add(match[1].toUpperCase());
  }}return [{json: {
    text,
    sections: [...found]
  }}];

